// Accounts, categories and prefs come from the Sheet on every pull; these defaults cover first launch and local-only use.
const defaultAccounts=()=>[['cash','Cash','⌑'],['tng','TNG eWallet','◉'],['shopeepay','ShopeePay','S'],['maybank','Maybank','M'],['wise','Wise','W']].map(([id,name,icon],i)=>({id,name,icon,openingBalance:0,sort:i+1,archived:false}));
const defaultCategories=()=>[...['Food & drinks','Fuel & transport','Mobile & internet','Bills & subscriptions','Family & giving','Social & lifestyle','Shopping','Healthcare','Education','Other'].map((name,i)=>({name,type:'expense',sort:i+1,archived:false})),...['Salary','Foodpanda','Other income','Refund / reimbursement','Gift received'].map((name,i)=>({name,type:'income',sort:i+1,archived:false}))];
const DEFAULT_PREFS={currency:'MYR',locale:'en-MY',timezone:'Asia/Kuala_Lumpur'};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>`&#${c.charCodeAt(0)};`);
// A blank or invalid value in the Settings tab falls back to the defaults instead of breaking every amount.
function usablePrefs(p){const x={...DEFAULT_PREFS,...Object.fromEntries(Object.entries(p||{}).filter(([,v])=>v))};try{new Intl.NumberFormat(x.locale,{style:'currency',currency:x.currency});new Intl.DateTimeFormat(x.locale,{timeZone:x.timezone});return x}catch{return {...DEFAULT_PREFS}}}
let state=JSON.parse(localStorage.getItem('my-money-v1')||'{"transactions":[],"settings":{"scriptUrl":""}}');
state.settings=state.settings||{};state.pendingOpening=state.pendingOpening||{};state.prefs=usablePrefs(state.prefs);
const fmt=n=>new Intl.NumberFormat(state.prefs.locale,{style:'currency',currency:state.prefs.currency,minimumFractionDigits:2}).format(n||0).replace('MYR','RM');
const symbol=()=>(new Intl.NumberFormat(state.prefs.locale,{style:'currency',currency:state.prefs.currency}).formatToParts(0).find(p=>p.type==='currency')?.value||'').replace('MYR','RM');
const save=()=>localStorage.setItem('my-money-v1',JSON.stringify(state));
const todayParts=()=>{const d=new Date();const parts=new Intl.DateTimeFormat('en-CA',{timeZone:state.prefs.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`};
const today=todayParts;const thisMonth=d=>d.slice(0,7)===today().slice(0,7);
const sorted=list=>[...list].sort((x,y)=>x.sort-y.sort);const active=list=>sorted(list.filter(x=>!x.archived));
const account=id=>state.accounts.find(a=>a.id===id);
if(!state.accounts){state.accounts=defaultAccounts();state.categories=defaultCategories();moveStartingBalances()}
// Entries for an account that's no longer in the Accounts tab are skipped, so totals never turn into NaN.
function transactionAmount(t,a){const add=(id,n)=>{if(Object.prototype.hasOwnProperty.call(a,id))a[id]+=n};if(t.type==='income'){add(t.account,t.amount);return}if(t.type==='expense'){add(t.account,-t.amount);return}add(t.account,-t.amount);add(t.destination,t.amount)}
function balances(){const a=Object.fromEntries(state.accounts.map(x=>[x.id,Number(x.openingBalance)||0]));state.transactions.forEach(t=>transactionAmount(t,a));return a}
function iconFor(t){return t.type==='income'?'↓':t.type==='expense'?'↑':'⇄'}
function row(t){const amount=t.type==='expense'?`−${fmt(t.amount)}`:t.type==='income'?`+${fmt(t.amount)}`:`${fmt(t.amount)}`;const label=t.type==='transfer'?`${name(t.account)} → ${name(t.destination)}`:t.category;return `<div class="transaction-row"><div class="transaction-icon">${iconFor(t)}</div><div><b>${esc(label)}</b><small>${esc(t.note||t.date)}</small></div><strong class="${t.type==='expense'?'out':t.type==='income'?'in':''}">${amount}</strong></div>`}
function name(id){return account(id)?.name||id}
function render(){const month=state.transactions.filter(t=>thisMonth(t.date));const income=month.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0);const spent=month.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0);const saved=income-spent;const a=balances();$('#month-label').textContent=new Intl.DateTimeFormat(state.prefs.locale,{month:'long',year:'numeric'}).format(new Date()).toUpperCase();$('#total-balance').textContent=fmt(Object.values(a).reduce((s,n)=>s+n,0));$('#month-income').textContent=`↓ ${fmt(income)} in`;$('#month-expense').textContent=`↑ ${fmt(spent)} out`;$('#saved-amount').textContent=fmt(saved);$('#spent-amount').textContent=fmt(spent);$('#saved-rate').textContent=income?`${Math.round(saved/income*100)}% of income kept`:'Add your first entry';$('#spent-count').textContent=`${month.filter(t=>t.type==='expense').length} transaction${month.filter(t=>t.type==='expense').length===1?'':'s'}`;
$('#accounts-list').innerHTML=sorted(state.accounts).filter(x=>!x.archived||Math.abs(a[x.id])>=0.005).map(x=>`<div class="account-row"><div class="account-icon">${esc(x.icon||[...x.name][0])}</div><div><b>${esc(x.name)}</b><small>${x.archived?'Archived':'Current balance'}</small></div><strong>${fmt(a[x.id])}</strong></div>`).join('');const latest=[...state.transactions].sort((x,y)=>y.date.localeCompare(x.date)).slice(0,5);const empty='<p class="empty-state">No entries yet — start with Money in or Spend.</p>';$('#recent-list').innerHTML=latest.length?latest.map(row).join(''):empty;$('#history-list').innerHTML=state.transactions.length?[...state.transactions].sort((x,y)=>y.date.localeCompare(x.date)).map(row).join(''):empty;
const cats={};month.filter(t=>t.type==='expense').forEach(t=>cats[t.category]=(cats[t.category]||0)+t.amount);const max=Math.max(...Object.values(cats),1);$('#category-chart').innerHTML=Object.keys(cats).length?Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([c,v])=>`<div class="category-row"><span>${esc(c)}</span><div class="bar"><i style="width:${v/max*100}%"></i></div><b>${fmt(v)}</b></div>`).join(''):'<p class="empty-state">Your spending pattern will appear here.</p>';
const year=today().slice(0,4),yr=state.transactions.filter(t=>t.date.startsWith(year));const yi=yr.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0),ye=yr.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0);$('#annual-summary').innerHTML=`<div><span>Income</span><b>${fmt(yi)}</b></div><div><span>Spent</span><b>${fmt(ye)}</b></div><div><span>Saved</span><b>${fmt(yi-ye)}</b></div>`;$('#annual-year').textContent=year;const months=Array.from({length:12},(_,i)=>String(i+1).padStart(2,'0'));const vals=months.map(m=>yr.filter(t=>t.type==='expense'&&t.date.slice(5,7)===m).reduce((s,t)=>s+t.amount,0)),high=Math.max(...vals,1);$('#year-bars').innerHTML=vals.map((v,i)=>`<div class="year-bar"><i style="height:${Math.max(2,v/high*112)}px"></i>${['J','F','M','A','M','J','J','A','S','O','N','D'][i]}</div>`).join('');const sources={};state.transactions.filter(t=>t.type==='income').forEach(t=>sources[t.category]=(sources[t.category]||0)+t.amount);const imax=Math.max(...Object.values(sources),1);$('#income-chart').innerHTML=Object.keys(sources).length?Object.entries(sources).map(([c,v])=>`<div class="category-row"><span>${esc(c)}</span><div class="bar"><i style="width:${v/imax*100}%"></i></div><b>${fmt(v)}</b></div>`).join(''):'<p class="empty-state">Income sources will appear after your first entry.</p>';if($('#manage-dialog').open)renderManage()}
// Pickers are filled when the form opens, so a background sync can't reset a half-filled entry.
function openEntry(type){const accountOptions=active(state.accounts).map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('');$('#account').innerHTML=accountOptions;$('#destination').innerHTML=accountOptions;$('.amount-field b').textContent=symbol();$('#entry-type').value=type;$('#entry-kicker').textContent=type==='income'?'MONEY IN':type==='expense'?'MONEY OUT':'TRANSFER';$('#entry-title').textContent=type==='income'?'Add income':type==='expense'?'Add spending':'Move money';$('#account-label').textContent=type==='income'?'Received in':type==='expense'?'Paid from':'From';$('#category-label').textContent=type==='income'?'Source':'Category';$('#note-label').innerHTML='Note <em>optional</em>';$('#note').placeholder=type==='income'?'e.g. March salary':type==='expense'?'e.g. ZUS Coffee':'e.g. Top up TNG';$('#destination-wrap').hidden=type!=='transfer';$('#category-wrap').hidden=type==='transfer';$('#category').innerHTML=active(state.categories.filter(c=>c.type===(type==='income'?'income':'expense'))).map(c=>`<option>${esc(c.name)}</option>`).join('');$('#date').value=today();$('#amount').value='';$('#note').value='';$('#entry-dialog').showModal();setTimeout(()=>$('#amount').focus(),50)}
$('#entry-form').addEventListener('submit',e=>{e.preventDefault();const type=$('#entry-type').value,amount=Number($('#amount').value),account=$('#account').value,destination=$('#destination').value;if(type==='transfer'&&account===destination)return toast('Choose a different destination account.');if(!amount||amount<=0)return;const t={id:crypto.randomUUID(),type,amount,account,destination:type==='transfer'?destination:'',category:type==='transfer'?'Transfer':$('#category').value,note:$('#note').value.trim(),date:$('#date').value,createdAt:Date.now(),synced:false};state.transactions.push(t);save();$('#entry-dialog').close();render();savedToast(()=>state.transactions.find(x=>x.id===t.id)?.synced);});
$$('.action').forEach(b=>b.addEventListener('click',()=>openEntry(b.dataset.type)));$$('.nav-item').forEach(b=>b.addEventListener('click',()=>{$$('.nav-item').forEach(x=>x.classList.toggle('active',x===b));$$('.page').forEach(x=>x.classList.toggle('active',x.id===b.dataset.page));window.scrollTo({top:0,behavior:'smooth'})}));
$$('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.closeDialog).close()));
function openBalances(){$('#balance-fields').innerHTML=active(state.accounts).map(a=>`<label><span>${esc(a.name)}</span><input data-balance-account="${esc(a.id)}" type="number" step="0.01" placeholder="0.00" value="${a.openingBalance||''}" /></label>`).join('');$('#balance-dialog').showModal()}
$('#balance-button').onclick=openBalances;
$('#balance-form').addEventListener('submit',e=>{e.preventDefault();$$('[data-balance-account]').forEach(inp=>{const a=account(inp.dataset.balanceAccount),amount=Math.round(Number(inp.value)*100)/100;if(!a||amount===(Number(a.openingBalance)||0))return;a.openingBalance=amount;state.pendingOpening[a.id]=amount;});state.onboarded=true;save();$('#balance-dialog').close();render();savedToast(()=>!Object.keys(state.pendingOpening).length);});
$('#settings-button').onclick=()=>{$('#script-url').value=state.settings.scriptUrl||'';$('#app-token').value=state.settings.appToken||'';$('#settings-dialog').showModal()};$('#settings-form').addEventListener('submit',e=>{e.preventDefault();state.settings.scriptUrl=$('#script-url').value.trim();state.settings.appToken=$('#app-token').value.trim();save();$('#settings-dialog').close();toast('Settings saved.');syncNow();});
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2800)}
// Every request carries the app token; the script refuses anything without it.
async function push(body){try{await fetch(state.settings.scriptUrl,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:JSON.stringify({...body,token:state.settings.appToken||''})});return true}catch{return false}}
// change(): add, rename, archive or delete an account or category. Unlike entries these need the script's reply (e.g. "used by 3 entries"),
// so they're sent as a normal request, only work online, and are followed by a reload. Resolves to {ok:true} or {ok:false, error}.
function change(body){return syncing=syncing.then(async()=>{if(!state.settings.scriptUrl){const reply=changeLocally(body);if(reply.ok){save();render()}return reply}if(navigator.onLine===false)return {ok:false,error:'You’re offline. Connect and try again.'};let reply;try{reply=await(await fetch(state.settings.scriptUrl,{method:'POST',headers:{'Content-Type':'text/plain'},body:JSON.stringify({...body,token:state.settings.appToken||''})})).json()}catch{reply={ok:false,error:'No reply from Google Sheets. Check the Sheet before trying again.'}}await pull();return reply})}
// Without a Sheet, the same changes and rules (see Code.gs) apply to this device only. Connecting a Sheet later replaces them with the Sheet's lists.
const fail=error=>({ok:false,error}),entries=n=>`${n} entr${n===1?'y':'ies'}`;
function changeLocally(b){const A=state.accounts,low=s=>String(s??'').trim().toLowerCase(),lastActive=(list,x)=>!x.archived&&list.filter(y=>!y.archived).length===1,next=list=>Math.max(0,...list.map(x=>x.sort))+1;
if(b.action==='reorder'){(b.list==='accounts'?A:state.categories.filter(c=>c.type===b.list)).forEach(x=>{const k=b.keys.indexOf(b.list==='accounts'?x.id:x.name);if(k>=0)x.sort=k+1});return {ok:true}}
if(/Account$/.test(b.action)){const a=b.account||{},id=b.id??a.id,x=A.find(y=>y.id===id);
  if(b.action==='saveAccount'){const name=String(a.name||'').trim();if(!name)return fail('Give the account a name');if(A.some(y=>y!==x&&(low(y.id)===low(name)||low(y.name)===low(name))))return fail(`Another account is already called "${name}"`);if(id&&!x)return fail(`No account with ID "${id}"`);let y=x;if(!y){const base=low(name).normalize('NFKD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')||'account';let nid=base;for(let n=2;A.some(z=>z.id===nid);n++)nid=`${base}-${n}`;y={id:nid,icon:'',openingBalance:0,sort:next(A),archived:false};A.push(y)}y.name=name;if(a.icon!==undefined)y.icon=[...a.icon.trim()].slice(0,2).join('');if(a.openingBalance!==undefined)y.openingBalance=a.openingBalance;return {ok:true,id:y.id}}
  if(!x)return fail(`No account with ID "${id}"`);
  if(b.action==='archiveAccount'){if(b.archived!==false&&lastActive(A,x))return fail('Keep at least one active account');x.archived=b.archived!==false;return {ok:true}}
  const used=state.transactions.filter(t=>t.account===id||t.destination===id).length;if(used)return fail(`${x.name} is used by ${entries(used)}. Archive it instead`);if(lastActive(A,x))return fail('Keep at least one active account');state.accounts=A.filter(y=>y!==x);return {ok:true}}
const c=b.category||{},type=low(c.type??b.type),list=state.categories.filter(y=>y.type===type),prev=String(c.previousName??b.name??'').trim(),x=list.find(y=>y.name===prev);
if(b.action==='saveCategory'){const name=String(c.name||'').trim();if(!['expense','income'].includes(type))return fail('Type must be expense or income');if(!name)return fail('Give the category a name');if(['transfer','starting balance'].includes(low(name)))return fail(`"${name}" is reserved`);if(list.some(y=>y!==x&&low(y.name)===low(name)))return fail(`There is already a category called "${name}"`);if(!prev){state.categories.push({name,type,sort:next(list),archived:false});return {ok:true}}if(!x)return fail(`No category called "${prev}"`);let renamed=0;state.transactions.forEach(t=>{if(t.type===type&&t.category===prev){t.category=name;renamed++}});x.name=name;return {ok:true,renamed}}
if(!x)return fail(`No category called "${prev}"`);
if(b.action==='archiveCategory'){if(b.archived!==false&&lastActive(list,x))return fail(`Keep at least one active ${type} category`);x.archived=b.archived!==false;return {ok:true}}
const used=state.transactions.filter(t=>t.type===type&&t.category===x.name).length;if(used)return fail(`"${x.name}" is used by ${entries(used)}. Archive it instead`);if(lastActive(list,x))return fail(`Keep at least one active ${type} category`);state.categories=state.categories.filter(y=>y!==x);return {ok:true}}
// Manage screens: one list dialog (accounts, or one type of category) and one edit dialog for either. Toasts sit behind open dialogs, so messages show inside them.
let manage='accounts',editing=null;
const manageItems=()=>manage==='accounts'?sorted(state.accounts):sorted(state.categories.filter(c=>c.type===manage));
function openManage(kind){manage=kind;$('#manage-note').textContent='';renderManage();if(!$('#manage-dialog').open)$('#manage-dialog').showModal()}
function renderManage(){const accounts=manage==='accounts',bal=balances(),items=manageItems();$('#manage-kicker').textContent=accounts?'YOUR MONEY':'YOUR CATEGORIES';$('#manage-title').textContent=accounts?'Accounts':'Categories';$('#manage-tabs').hidden=accounts;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===manage));$('#manage-add').textContent=accounts?'Add account':manage==='income'?'Add income source':'Add category';
$('#manage-list').innerHTML=items.length?items.map((x,i)=>{const detail=accounts?fmt(bal[x.id]):entries(state.transactions.filter(t=>t.type===x.type&&t.category===x.name).length);return `<div class="account-row manage-row${x.archived?' archived':''}"><div class="account-icon">${esc(accounts&&x.icon||[...x.name][0])}</div><button type="button" class="manage-open" data-edit="${i}"><b>${esc(x.name)}</b><small>${detail}${x.archived?' · Archived':''}</small></button><button type="button" class="move-button" data-move="${i}" data-dir="-1" aria-label="Move ${esc(x.name)} up"${i?'':' disabled'}>↑</button><button type="button" class="move-button" data-move="${i}" data-dir="1" aria-label="Move ${esc(x.name)} down"${i<items.length-1?'':' disabled'}>↓</button></div>`}).join(''):'<p class="empty-state">Nothing here yet.</p>'}
function openItem(x){const accounts=manage==='accounts';editing=x||null;$('#item-note').textContent='';$('#item-kicker').textContent=accounts?'ACCOUNT':manage==='income'?'INCOME SOURCE':'SPENDING CATEGORY';$('#item-title').textContent=x?`Edit ${x.name}`:$('#manage-add').textContent;$('#item-account-fields').hidden=!accounts;$('#item-name').value=x?x.name:'';$('#item-icon').value=x&&accounts?x.icon:'';$('#item-opening').value=x&&accounts&&x.openingBalance?x.openingBalance:'';$('#item-archive').hidden=$('#item-delete').hidden=!x;if(x)$('#item-archive').textContent=x.archived?'Unarchive':'Archive';$('#item-dialog').showModal();setTimeout(()=>$('#item-name').focus(),50)}
// Runs one change with the dialogs' buttons disabled. An error shows in the dialog it came from; success closes the edit dialog and notes it on the list.
async function busy(request,note){const buttons=$$('#manage-dialog button,#item-dialog button');buttons.forEach(b=>b.disabled=true);$('#item-note').textContent=$('#manage-note').textContent='';const reply=await request;buttons.forEach(b=>b.disabled=false);
  if(!reply.ok){const where=$('#item-dialog').open?'#item-note':'#manage-note';$(where).className='form-note error';$(where).textContent=reply.error}
  else{$('#item-dialog').close();$('#manage-note').className='form-note';$('#manage-note').textContent=typeof note==='function'?note(reply):note}renderManage()}
$('#accounts-button').onclick=()=>openManage('accounts');$('#categories-button').onclick=()=>{$('#settings-dialog').close();openManage('expense')};$$('[data-tab]').forEach(b=>b.onclick=()=>openManage(b.dataset.tab));$('#manage-add').onclick=()=>openItem();
$('#manage-list').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const items=manageItems();if(b.dataset.edit)return openItem(items[b.dataset.edit]);const i=+b.dataset.move,j=i+(+b.dataset.dir);if(!items[j])return;[items[i],items[j]]=[items[j],items[i]];busy(change({action:'reorder',list:manage,keys:items.map(x=>manage==='accounts'?x.id:x.name)}),'')});
$('#item-form').addEventListener('submit',e=>{e.preventDefault();const name=$('#item-name').value.trim(),x=editing;if(!name)return;
  if(manage==='accounts'){const account={name,icon:$('#item-icon').value.trim()},opening=Math.round(Number($('#item-opening').value)*100)/100;if(x)account.id=x.id;
    // Sent only when changed; it then replaces any opening balance still waiting to upload from the balances dialog.
    if(!x||opening!==(Number(x.openingBalance)||0)){account.openingBalance=opening;if(x)delete state.pendingOpening[x.id]}
    return busy(change({action:'saveAccount',account}),`${x?'Saved':'Added'} ${name}.`)}
  busy(change({action:'saveCategory',category:{name,type:manage,...(x?{previousName:x.name}:{})}}),r=>r.renamed?`Renamed to ${name}. ${entries(r.renamed)} updated.`:`${x?'Saved':'Added'} ${name}.`)});
$('#item-archive').onclick=()=>{const x=editing,v=!x.archived;busy(change(manage==='accounts'?{action:'archiveAccount',id:x.id,archived:v}:{action:'archiveCategory',name:x.name,type:x.type,archived:v}),`${x.name} ${v?'archived':'is back'}.`)};
$('#item-delete').onclick=()=>{const x=editing;if(!confirm(`Delete ${x.name}? This can't be undone.`))return;busy(change(manage==='accounts'?{action:'deleteAccount',id:x.id}:{action:'deleteCategory',name:x.name,type:x.type}),`Deleted ${x.name}.`)};
// syncNow(): send unsynced entries and opening balances, then reload from the Sheet. Runs one at a time so quick saves never send a row twice.
let syncing=Promise.resolve();
function syncNow(){return syncing=syncing.then(async()=>{if(!state.settings.scriptUrl||navigator.onLine===false)return;const pending=state.transactions.filter(t=>!t.synced);if(pending.length)await push({action:'appendTransactions',transactions:pending});if(Object.keys(state.pendingOpening).length)await push({action:'setOpeningBalances',balances:state.pendingOpening});await pull()})}
function savedToast(done){if(!state.settings.scriptUrl)return toast('Saved on this device. Add your Sheet URL in Settings to sync.');toast('Saving to Google Sheets…');syncNow().then(()=>toast(done()?'Saved to Google Sheets.':syncError?`Saved on this device. ${syncError}`:'Saved on this device. It will upload when you are back online.'))}
// Older versions kept opening balances as 'Starting balance' income rows. The newest per account becomes its opening balance, queued for upload if the Sheet never got it.
function moveStartingBalances(){const latest={};state.transactions.filter(t=>t.category==='Starting balance').forEach(t=>{if(!latest[t.account]||t.createdAt>latest[t.account].createdAt)latest[t.account]=t});Object.values(latest).forEach(t=>{const a=account(t.account);if(!a)return;a.openingBalance=t.amount;if(!t.synced)state.pendingOpening[a.id]=t.amount});state.transactions=state.transactions.filter(t=>t.category!=='Starting balance')}
// An opening balance changed on this device stays pending, and shown, until the Sheet reports the same value.
function applyPendingOpening(){Object.entries(state.pendingOpening).forEach(([id,n])=>{const a=account(id);if(!a||Math.abs(a.openingBalance-n)<0.005)delete state.pendingOpening[id];else a.openingBalance=n})}
// pull(): the Sheet is the source of truth for entries, accounts, categories and prefs. synced = "seen in the Sheet", so a synced row missing there was deleted there.
// syncError: why the last pull was refused (e.g. a wrong token), so the save toast doesn't blame the connection.
let syncError='';
async function pull(){const url=state.settings.scriptUrl;if(!url)return;try{const data=await(await fetch(`${url}${url.includes('?')?'&':'?'}token=${encodeURIComponent(state.settings.appToken||'')}`)).json();if(!data.ok){syncError=`Google Sheets refused it: ${data.error||'unknown error'}.`;return toast(syncError)}syncError='';const ids=new Set(data.transactions.map(t=>t.id));state.transactions=[...data.transactions.map(t=>({...t,synced:true})),...state.transactions.filter(t=>!t.synced&&!ids.has(t.id))];if(data.accounts){state.accounts=data.accounts;state.categories=data.categories;state.prefs=usablePrefs(data.settings)}moveStartingBalances();applyPendingOpening();if(state.accounts.some(a=>a.openingBalance))state.onboarded=true;save();render()}catch{toast('Could not load from Google Sheets.')}}
$('#resync-button').onclick=()=>{if(!state.settings.scriptUrl)return toast('Add your Apps Script URL first.');if(confirm('Resend every entry to the Sheet? Already-synced rows will not be duplicated there.'))push({action:'appendTransactions',transactions:state.transactions}).then(ok=>{toast(ok?`${state.transactions.length} entries sent to Google Sheets.`:'Could not reach Google Sheets.');pull()});};
$('#clear-button').onclick=()=>{if(confirm('Clear all locally saved transactions? Your Google Sheet is not changed.')){state.transactions=[];save();$('#settings-dialog').close();render();toast('Local data cleared.')}};$('#history-button').onclick=()=>document.querySelector('[data-page="history-page"]').click();$('#export-button').onclick=()=>{const rows=[['Date','Type','Account','Destination','Category','Amount','Note'],...state.transactions.map(t=>[t.date,t.type,name(t.account),t.destination?name(t.destination):'',t.category,t.amount,t.note])];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.map(r=>r.map(x=>`"${String(x).replaceAll('"','""')}"`).join(',')).join('\n')],{type:'text/csv'}));a.download='my-money-transactions.csv';a.click()};
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');if(!state.onboarded)openBalances();syncNow();
// Home-screen shortcuts (manifest.json) open ./?add=expense etc. straight into the entry form.
const add=new URLSearchParams(location.search).get('add');if(['income','expense','transfer'].includes(add)){history.replaceState(null,'',location.pathname);if(state.onboarded)openEntry(add)}
window.addEventListener('online',syncNow);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')syncNow()});
